import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十三章","description":"《正易心法》第二十三章——古今传易，舛讹为多：论证履当在小畜之上（一柔变化序列、《龙图大衍》定数、反对义三重）与八体当为艮鼻巽手，是全书对传易文献的批评章。","frontmatter":{"title":"正易心法·第二十三章","description":"《正易心法》第二十三章——古今传易，舛讹为多：论证履当在小畜之上（一柔变化序列、《龙图大衍》定数、反对义三重）与八体当为艮鼻巽手，是全书对传易文献的批评章。","category":"guide","aliases":["正易心法第二十三章","古今传易舛讹为多","履畜八体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-23.md","filePath":"yijing/zheng-yi-xin-fa/chapter-23.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-23.md"},x=r({...c,setup(u){const i=[{id:"z23-01",label:"一、舛讹为多",showLabel:!0,sentences:[["古今传易，",{text:"舛讹",glossary:"chuanE"},"为多。履畜八体，最为",{text:"害义",glossary:"haiyi"},"。"]],note:["古往今来传授《易》学，错误很多：其中履卦与小畜的卦序问题、以及八卦对应八体的问题，是最损害义理的错误。（这是全书的**文献批评章**——前二十二章用义理建立体系，本章用这个体系来检验传本。**「舛讹为多」四个字，是麻衣对传世文献的基本判断。**）"]},{id:"z23-02",label:"二、履先小畜",showLabel:!0,sentences:[["按卦序，当先履而后小畜。今小畜在先，则二卦画象反对，文义",{text:"缪乱",glossary:"miuluan"},"，而不可考。"]],note:["按照卦序，应当先是履卦、然后才是小畜。现在小畜排在前面，则这两卦的卦画象反对关系混乱，文义错乱，无法考证。（**履与小畜互为反卦**：履䷉（乾上兑下）翻转即得小畜䷈（巽上乾下）。按第十六章「反对」的原则，反卦应当相邻而有序——**先正后反（先履后小畜）**；今本颠倒，故曰「缪乱」。）"]},{id:"z23-03",label:"三、八体之误",showLabel:!0,sentences:[["又以八卦本对八体，独",{text:"阕其鼻",glossary:"queqibi"},"。乃以巽言",{text:"股",glossary:"gu"},"，股即系是也。若股可言，则又遗其肱，且与羲皇八卦不相应也。兹盖传者舛误耳，能不害义乎？"]],note:["又因为八卦本来对应人体八个部位，却唯独缺少了鼻子；于是用巽卦对应大腿。如果大腿可以说，那么又遗漏了手臂，而且与伏羲八卦不相应。这大概是传授者的错误，怎么能不损害义理呢？（今本《说卦传》作「巽为股，艮为手」——**有「股」（大腿）而无「鼻」，有「手」而失对待，身体既不完整、逻辑也混乱。**）"]},{id:"z23-04",label:"四、一柔一刚之序",showLabel:!0,sentences:[["试辨之，一柔自姤变同人，同人变履，履变小畜，小畜变大有，犹之一刚自复变师，又变谦，又变豫，又变比，皆自然之序不易也。今谦既在豫上，则知履不当在小畜下。"]],note:["试加以辨析：一柔自姤卦变化——姤变同人、同人变履、履变小畜、小畜变大有；正如一刚自复卦变化——复变师、又变谦、又变豫、又变比，都是自然的顺序，不可更改。现在谦卦既然在豫卦之前，就知道履卦不应当排在小畜之后。（**用「一柔」与「一刚」两条平行序列作类比**：既然「刚」的序列里谦在豫之前，那么「柔」的序列里履就应在小畜之前。**今本谦（第十五）在豫（第十六）之前是对的，而小畜（第九）在履（第十）之前就错了。**）"]},{id:"z23-05",label:"五、龙图定数",showLabel:!0,sentences:[["当密探",{text:"宣尼",glossary:"xuanni"},"述",{text:"九卦",glossary:"jiugua"},"，以履为用九，谦用十五，复用二十四，皆《",{text:"龙图大衍",glossary:"longtuDayan"},"》定数。则履在小畜上，为第九卦也明矣。"]],note:["应当仔细探究孔子所论述的九卦：以履为「用九」，谦用十五，复用二十四，都是《龙图大衍》的定数。那么履卦在小畜之上、为第九卦，就很清楚了。（孔子《系辞下》述九卦为「履、谦、复、恒、损、益、困、井、巽」。今本卦序中**谦正是第十五卦、复正是第二十四卦**——与定数吻合；**唯独履是第十卦，与「用九」不符。三个定数中两个已合，只有一个不合，这就是麻衣指出错位的那一个。**）"]},{id:"z23-06",label:"六、失其本真",showLabel:!0,sentences:[["又履与无妄对义，既以大畜反无妄而居下，则知小畜反履而居下无疑矣。今序卦非宣尼旨，失其本真也。"]],note:["又：履与无妄是对义关系；既然大畜作为无妄的反卦而排在无妄之后，那么小畜作为履的反卦而排在履之后，也就毫无疑问了。现在的《序卦传》不是孔子的本意，失去了原本的真实面目。（**三条论证并出：一柔序列的类比、《龙图大衍》定数、反对义关系。** 值得注意的是麻衣的分寸——**「今序卦非宣尼旨」：错的是传本，不是孔子。** 这与第四章「不得已而有辞」的立场一致。）"]},{id:"z23-07",label:"七、艮鼻巽手",showLabel:!0,sentences:[["八体，乃艮为鼻，巽为手耳。《传》曰：“鼻者，面之山也。”又曰：“风能鼓舞万物，而手之所以舞也。”"]],note:["八体应当是艮为鼻、巽为手。《传》说「鼻子是面部的山」（艮为山，鼻是面部最突出之处）；又说「风能鼓舞万物，而手正是用来舞动的」（巽为风，手最能动）。**这一改，八体就完整了：首、腹、耳、目、鼻、口、手、足——正是头面五官加躯干四肢。**）"]},{id:"z23-08",label:"八、八卦之应",showLabel:!0,sentences:[["盖乾为首，坤为腹，天地定位也。坎为耳，离为目，水火相逮也。艮为鼻，兑为口，山泽通气也。巽为手，震为足，雷风相薄也。此羲皇八卦之应矣，其理昭昭。"]],note:["乾为首、坤为腹——天地定位；坎为耳、离为目——水火相逮；艮为鼻、兑为口——山泽通气；巽为手、震为足——雷风相薄。这才是伏羲八卦与人体的对应，其道理昭然明白。（**四对全是先天八卦的「对待」关系**：乾坤（天地）、坎离（水火）、艮兑（山泽）、震巽（雷风）——**这就是麻衣判定的标准：八体对应必须符合先天八卦的对待结构。** 今本「巽为股、艮为手」恰恰破坏了这四对。）"]},{id:"z23-09",label:"九、承误效尤",showLabel:!0,sentences:[["但学者",{text:"承误效尤",glossary:"chengwuXiaoyou"},"，见不高远，其失至此。真人",{text:"闵",glossary:"min"},"之，故开其眼目。"]],note:["只是学者沿袭错误、效仿过失，见识不够高远，才造成这样的失误。真人怜悯这种情况，所以开启学者的眼界。（**「真人闵之，故开其眼目」是麻衣少见的自我指认**——在他看来这两个错误不是学术细枝末节，是「眼睛」的问题：**看错了，就什么都错了。**）"]}],l=[{id:"chuanE",term:"舛讹",pinyin:"chuǎn é",meaning:"错乱与讹误。舛是错乱，讹是错误。指传易过程中的错误。"},{id:"haiyi",term:"害义",pinyin:"hài yì",meaning:"损害义理。错误导致义理无法正确理解。"},{id:"miuluan",term:"缪乱",pinyin:"miù luàn",meaning:"混乱错误。缪通「谬」。"},{id:"queqibi",term:"阕其鼻",pinyin:"què qí bí",meaning:"唯独缺失了鼻子。阕是缺失。八体中鼻子被遗漏了。"},{id:"gu",term:"股",pinyin:"gǔ",meaning:"大腿。今本《说卦传》以巽为股，麻衣认为「股」有误（当为手）。"},{id:"xuanni",term:"宣尼",pinyin:"xuān ní",meaning:"孔子的字。汉平帝追谥孔子为「褒成宣尼公」，故称。"},{id:"jiugua",term:"九卦",pinyin:"jiǔ guà",meaning:"《系辞下》所述九卦：履、谦、复、恒、损、益、困、井、巽。麻衣据其定数校正卦序。"},{id:"longtuDayan",term:"龙图大衍",pinyin:"lóng tú dà yǎn",meaning:"河图与大衍之数的体系。麻衣所引的数理来源。"},{id:"chengwuXiaoyou",term:"承误效尤",pinyin:"chéng wù xiào yóu",meaning:"继承错误、效仿过失。后人沿袭前人的错误。"},{id:"min",term:"闵",pinyin:"mǐn",meaning:"怜悯、忧虑。「真人闵之」即麻衣怜悯这种情况。"}];return(b,n)=>{const o=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十三章" tabindex="-1">正易心法·第二十三章 <a class="header-anchor" href="#正易心法·第二十三章" aria-label="Permalink to &quot;正易心法·第二十三章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是《正易心法》的<strong>文献批评章</strong>，提出两个具体的传易错误：</p><p><strong>错误一：卦序错误</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今本：小畜（第九）→ 履（第十）</span></span>
<span class="line"><span>正确：履（第九）→ 小畜（第十）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三重论证：</span></span>
<span class="line"><span>  ① 一柔变化序列（类比一刚序列）</span></span>
<span class="line"><span>  ② 《龙图大衍》定数（履用九＝第九）</span></span>
<span class="line"><span>  ③ 反对义关系（小畜是履的反卦，应在后）</span></span></code></pre></div><p><strong>错误二：八体错误</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今本：巽为股，艮为手</span></span>
<span class="line"><span>正确：艮为鼻，巽为手</span></span>
<span class="line"><span></span></span>
<span class="line"><span>四重理由：</span></span>
<span class="line"><span>  ① 今本有股无鼻，身体不完整</span></span>
<span class="line"><span>  ② 艮为鼻（面之山），象义相符</span></span>
<span class="line"><span>  ③ 巽为手（风能舞，手能舞），象义相符</span></span>
<span class="line"><span>  ④ 四对对待结构（乾坤、坎离、艮兑、震巽）完整</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「一柔」与「一刚」两条平行序列</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一柔序列：姤 → 同人 → 履 → 小畜 → 大有</span></span>
<span class="line"><span>一刚序列：复 → 师 → 谦 → 豫 → 比</span></span></code></pre></div><p><strong>今本中谦（第十五）在豫（第十六）之前是对的；同理，履应在小畜之前。</strong></p><p><strong>《龙图大衍》定数的三验</strong>：</p><table tabindex="0"><thead><tr><th>卦</th><th>定数</th><th>今本卦序</th><th>合否</th></tr></thead><tbody><tr><td>履</td><td>用九（第九）</td><td>第十</td><td>✗</td></tr><tr><td>谦</td><td>用十五</td><td>第十五</td><td>✓</td></tr><tr><td>复</td><td>用二十四</td><td>第二十四</td><td>✓</td></tr></tbody></table><p><strong>三个定数中两个已合，只有一个不合——这就是麻衣指出错位的那一个。</strong></p><p><strong>八体的四对对待</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾为首、坤为腹     —— 天地定位</span></span>
<span class="line"><span>坎为耳、离为目     —— 水火相逮</span></span>
<span class="line"><span>艮为鼻、兑为口     —— 山泽通气</span></span>
<span class="line"><span>巽为手、震为足     —— 雷风相薄</span></span></code></pre></div><p><strong>四对全是先天八卦的「对待」关系</strong>——这既是麻衣判定的标准，也是今本「巽为股、艮为手」被判定为误的根据：它破坏了这四对。</p><p><strong>麻衣的分寸</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「今序卦非宣尼旨，失其本真也」</span></span>
<span class="line"><span>= 错的是传本，不是孔子</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这是一种既尊重孔子、又敢于批评今本的立场：</span></span>
<span class="line"><span>错误不在孔子，在传抄者</span></span>
<span class="line"><span>回归孔子的「本真」，才是真正尊重孔子</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先分清本章的两个议题：<strong>卦序（履小畜）与八体（艮鼻巽手）</strong>；</li><li>再看卦序的三条论证：<strong>序列类比、定数、反对义</strong>；</li><li>最后看八体的标准：<strong>四对对待结构</strong>。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>舛讹为多</strong>：传易过程中错误很多。</li><li><strong>履小畜之序</strong>：履当在小畜之上（第九）。</li><li><strong>一柔一刚序列</strong>：两条平行序列的类比。</li><li><strong>龙图大衍定数</strong>：履用九、谦用十五、复用二十四。</li><li><strong>八体</strong>：艮为鼻、巽为手。</li><li><strong>四对对待</strong>：乾坤、坎离、艮兑、震巽。</li><li><strong>真人闵之</strong>：开启学者的眼界。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,24)),e(o,{colophon:"舛讹为多 · 履畜之序 · 八体正误 · 羲皇八卦之应",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十三章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「一柔自姤变同人」「一刚自复变师」诸句及「龙图大衍」定数随底本，不作统一；本章所论为麻衣一家之说，读者可参看《系辞下》九卦与今本《说卦传》八体自行对勘。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"舛讹",pinyin:["chuǎn","é"],meaning:"错乱与讹误。麻衣对传世文献的基本判断：「古今传易，舛讹为多」。"},{term:"履当在小畜上",pinyin:["lǚ","dāng"],meaning:"麻衣主张履为第九卦、小畜为第十卦，而今本相反。三重论证：一柔序列、龙图定数、反对义。"},{term:"龙图大衍定数",pinyin:["lóng","tú"],meaning:"履用九、谦用十五、复用二十四——今本谦与复皆合，唯履不合，故知履当在上。"},{term:"艮为鼻，巽为手",pinyin:["gèn","wéi"],meaning:"麻衣对《说卦传》八体的纠正。标准是先天八卦的四对对待：乾坤、坎离、艮兑、震巽。"},{term:"承误效尤",pinyin:["chéng","wù"],meaning:"继承错误、效仿过失。麻衣批评学者「见不高远，其失至此」。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>文献批评章</strong>，提出两个具体的传易错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误一：卦序——履当在小畜之上（第九）</span></span>
<span class="line"><span>  三重论证：① 一柔变化序列 ②《龙图大衍》定数 ③ 反对义关系</span></span>
<span class="line"><span>错误二：八体——当为艮为鼻、巽为手</span></span>
<span class="line"><span>  理由：① 今本有股无鼻，身体不完整 ② 艮鼻象义相符 ③ 巽手象义相符</span></span>
<span class="line"><span>       ④ 四对对待结构（乾坤、坎离、艮兑、震巽）完整</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>两个议题都是同一个问题的表现</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦序错误 → 反对关系混乱 → 义理无法正确理解</span></span>
<span class="line"><span>八体错误 → 象义不符     → 取象无法正确运用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者都违背了：</span></span>
<span class="line"><span>  ① 伏羲八卦的原始对待结构</span></span>
<span class="line"><span>  ② 阴阳消长的自然序列</span></span>
<span class="line"><span>  ③ 象义相符的基本原则</span></span></code></pre></div><p><strong>麻衣的学术勇气与分寸</strong>：他批评的是《序卦传》《说卦传》——传统认为孔子所作。但他的判断是「<strong>今序卦非宣尼旨，失其本真也</strong>」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误不在孔子，在传抄者</span></span>
<span class="line"><span>= 回归孔子的「本真」，才是真正尊重孔子</span></span></code></pre></div><p><strong>「真人闵之，故开其眼目」</strong>——这是本章（也是全书）少见的麻衣以「真人」自称之处：<strong>表明这不是普通的学术争论，而是从「道」的高度来纠正错误。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>先分清两个议题：<strong>卦序与八体</strong>；</li><li>再看卦序的三条论证：<strong>序列类比、定数、反对义</strong>；</li><li>最后看八体的标准：<strong>四对对待结构</strong>；</li><li>带着一个问题往下读：<strong>麻衣批评别人「承误效尤」，那我们读麻衣，是否也需要同样的眼光？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>古往今来传授《易》学，错误很多：其中履卦与小畜的卦序问题、以及八卦对应八体的问题，是最损害义理的错误。</p><p>按照卦序，应当先是履卦，然后才是小畜。现在小畜排在前面，则这两卦的卦画象反对关系混乱，文义错乱，无法考证。又因为八卦本来对应人体八个部位，却唯独缺少了鼻子；于是用巽卦对应大腿，大腿就是腿的意思。如果大腿可以说，那么又遗漏了手臂，而且与伏羲八卦不相应。这大概是传授者的错误，怎么能不损害义理呢？</p><p>试加以辨析：一柔自姤卦变化——姤变同人、同人变履、履变小畜、小畜变大有；正如一刚自复卦变化——复变师、又变谦、又变豫、又变比，都是自然的顺序，不可更改。现在谦卦既然在豫卦之前，就知道履卦不应当排在小畜之后。</p><p>应当仔细探究孔子所论述的九卦：以履为「用九」，谦用十五，复用二十四，都是《龙图大衍》的定数。那么履卦在小畜之上、为第九卦，就很清楚了。</p><p>又：履与无妄是对义关系；既然大畜作为无妄的反卦而排在无妄之后，那么小畜作为履的反卦而排在履之后，也就毫无疑问了。现在的《序卦传》不是孔子的本意，失去了原本的真实面目。</p><p>八体应当是艮为鼻、巽为手。《传》说「鼻子是面部的山」，又说「风能鼓舞万物，而手正是用来舞动的」。</p><p>乾为首、坤为腹——天地定位；坎为耳、离为目——水火相逮；艮为鼻、兑为口——山泽通气；巽为手、震为足——雷风相薄。这才是伏羲八卦与人体的对应，其道理昭然明白。只是学者沿袭错误、效仿过失，见识不够高远，才造成这样的失误。真人怜悯这种情况，所以开启学者的眼界。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十三章是麻衣「动手改课本」的一章——<strong>他指出两个具体的错，并给出三重、四重的证据；而他的分寸是：错在传抄，不在孔子。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「舛讹为多」</strong>——这是麻衣对传世文献的基本判断。<strong>他不是恭敬地接受一切旧本，而是先建立义理标准，再回头检查文本。</strong></li><li><strong>一柔与一刚的两条序列</strong>——这是本章最漂亮的一步：<strong>用「刚」的序列做参照，来定「柔」的序列。</strong> 既然谦在豫之前（今本如此），履就应在小畜之前。<strong>这不是猜，是类比推理。</strong></li><li><strong>「三个定数，两个合」</strong>——履用九、谦用十五、复用二十四。<strong>今本谦、复都合，只有履不合。</strong> 这个论证很硬：<strong>如果三个数是乱的，就不能用；两个已合，说明体系本身是对的，那一处不合的，就是错的。</strong></li><li><strong>「今序卦非宣尼旨」</strong>——这一句最有分寸。<strong>麻衣不改孔子的权威，只改传本的错误。</strong> 这与第四章「不得已而有辞」的立场完全一致：<strong>错的不是圣人，是后人。</strong></li><li><strong>八体的四对对待</strong>——乾坤、坎离、艮兑、震巽。<strong>这是先天八卦的结构，麻衣用它来判定哪一对是对的。</strong> 今本「巽为股、艮为手」破坏了这四对，所以是错的。</li><li><strong>「真人闵之，故开其眼目」</strong>——麻衣很少自称「真人」，这里出现，说明<strong>在他看来这不是学术细枝末节，是「眼睛」的问题：看错了，就什么都错了。</strong></li><li><strong>留给自己的问题</strong>：<strong>我们读《正易心法》本身，也是经过历代传抄的文本（第二十章的「太始」、第三十一章的「缺卦」、第四十一章的「良田」都留有痕迹）。那么麻衣批评别人「承误效尤」的精神，是否也应当用在他自己身上？</strong> 我的看法：<strong>是的，而且这正是他要的。</strong> 「义实通明」，不只是读懂文本，也包括<strong>质疑文本本身</strong>——<strong>一部反对「盲诵」的书，也要求读者不盲诵它自己。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 「错在传人，不在圣人」的同一立场</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对</a> — 反对义（本章「反对义之证」的依据）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 回归「羲皇八卦」的原始结构</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 见于日用</a> — 破（本章）与立（下章）</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 本章所纠的卦序</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 本章所纠的八体</li></ul>`,26))])}}});export{y as __pageData,x as default};
